function validate([word, k]) {
  if (typeof word !== 'string' || word.length < 1 || word.length > 1000000) return 'word needs 1 to 10^6 characters.';
  if (!/^[a-z]+$/.test(word)) return 'word uses only lowercase English letters.';
  if (!Number.isInteger(k) || k < 1 || k > word.length) return 'k is between 1 and word.length.';
  return null;
}

