function minimumTimeToInitialState(word, k) {
  const n = word.length;
  const z = new Array(n).fill(0);
  let left = 0;
  let right = 0;

  for (let i = 1; i < n; i++) {
    if (i < right) {
      z[i] = Math.min(right - i, z[i - left]);
    }
    while (i + z[i] < n && word[z[i]] === word[i + z[i]]) {
      z[i]++;
    }
    if (i + z[i] > right) {
      left = i;
      right = i + z[i];
    }
  }

  let time = 1;
  while (time * k < n) {
    const start = time * k;
    if (z[start] === n - start) {
      return time;
    }
    time++;
  }
  return time;
}

