function generate(rand, size) {
  const letters = 'abc';
  if (size === 'small') {
    const n = 1 + Math.floor(rand() * 12);
    const alphabet = 1 + Math.floor(rand() * 3);
    const period = 1 + Math.floor(rand() * n);
    const base = Array.from({ length: period }, () => letters[Math.floor(rand() * alphabet)]).join('');
    const chars = Array.from({ length: n }, (_, i) => base[i % period]);
    if (rand() < 0.3) chars[Math.floor(rand() * n)] = letters[Math.floor(rand() * 3)];
    const k = 1 + Math.floor(rand() * n);
    return [chars.join(''), k];
  }
  const n = 10000;
  const period = 1 + Math.floor(rand() * 40);
  const base = Array.from({ length: period }, () => letters[Math.floor(rand() * 2)]).join('');
  const chars = Array.from({ length: n }, (_, i) => base[i % period]);
  if (rand() < 0.5) chars[n - 1 - Math.floor(rand() * 50)] = 'z';
  const k = 1 + Math.floor(rand() * 60);
  return [chars.join(''), k];
}
